 draw();loadCitySummaries();scheduleViewportLoad();updatePlacesMap(false);if(selectedBusinessId)fetch(`/api/organization?id=${encodeURIComponent(selectedBusinessId)}`,{headers:{Accept:"application/json"}}).then(response=>response.ok?response.json():null).then(data=>{const item=data?.item;if(item&&hasMapPoint(item)){map.setView([item.lat,item.lon],15,{animate:true});scheduleViewportLoad()}}).catch(()=>{});setTimeout(()=>map.invalidateSize(),100);
