function addForm(){
 const f=$("addForm");if(!f)return;const citySelect=$("city"),customCity=$("customCity"),customRegion=$("customRegion");let extraCities=[];try{extraCities=JSON.parse(localStorage.getItem("localhub:cities")||"[]");if(!Array.isArray(extraCities))extraCities=[]}catch{}
 if(citySelect){CITIES.forEach(c=>citySelect.add(new Option(c.name,c.name)));extraCities.forEach(c=>{if(c?.name&&!CITIES.some(x=>x.name===c.name))citySelect.add(new Option(c.name,c.name))});citySelect.add(new Option("Другой город…","__other"))}
 const updateCustomCity=()=>{const custom=citySelect?.value==="__other";if(customCity){customCity.hidden=!custom;customCity.required=custom}if(customRegion){customRegion.hidden=!custom;customRegion.required=custom}};citySelect?.addEventListener("change",updateCustomCity);
 f.addEventListener("submit",async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));const custom=d.city==="__other",cityName=custom?(d.customCity||"").trim():d.city,region=custom?(d.customRegion||"").trim():null;const lat=d.lat?Number(d.lat):null,lon=d.lon?Number(d.lon):null;if((lat===null)!==(lon===null)||(lat!==null&&(!Number.isFinite(lat)||lat < -90||lat > 90||!Number.isFinite(lon)||lon < -180||lon > 180))){$("formError").hidden=false;return}$("formError").hidden=true;const item={id:crypto.randomUUID(),name:d.name.trim(),category:d.category,city:cityName,region,address:d.address.trim(),lat,lon,phone:d.phone.trim()||null,website:d.website.trim()||null,photo:d.photo.trim()||null,source:d.source.trim()||"Добавлено пользователем",updatedAt:new Date().toISOString().slice(0,10)};let list;try{list=JSON.parse(localStorage.getItem("localhub:pending")||"[]");if(!Array.isArray(list))list=[]}catch{list=[]}const cloud=window.LocalHubAuth;if(cloud?.user){const submit=f.querySelector("[type=submit]");if(submit)submit.disabled=true;const result=await cloud.submitOrganization(item);if(submit)submit.disabled=false;if(result.error){$("formError").textContent=result.error.message||"Не удалось отправить предложение.";$("formError").hidden=false;return}$("formError").hidden=true;$("formSuccess").textContent="Предложение отправлено и ожидает проверки модератором.";$("formSuccess").hidden=false;f.reset();updateCustomCity();return}list.push(item);localStorage.setItem("localhub:pending",JSON.stringify(list));if(item.city&&!CITIES.some(c=>c.name===item.city)){const cities=readLocal("localhub:cities",[]).filter(c=>c.name!==item.city);cities.push({name:item.city,region:item.region||"Не указано"});writeLocal("localhub:cities",cities)}$("formSuccess").textContent="Черновик сохранён только в этом браузере. Войдите в настроенный аккаунт, чтобы отправить его на модерацию.";$("formSuccess").hidden=false;f.reset();updateCustomCity()})
}function initPlacesSearch(){
 const form=$("placesSearchForm");if(!form)return;
 const city=$("placesCity"),categorySelect=$("placesCategory"),status=$("placesSearchStatus"),results=$("placesResults"),head=$("placesResultsHead"),pagination=$("placesPagination"),button=$("placesSearchButton"),selectedButton=$("placesSelectedMap");
 CITIES.forEach(item=>city.add(new Option(item.name,item.name)));
 try{JSON.parse(localStorage.getItem("localhub:cities")||"[]").forEach(item=>{if(item?.name&&!CITIES.some(c=>c.name===item.name))city.add(new Option(item.name,item.name))})}catch{}
 CATEGORIES.forEach(item=>categorySelect.add(new Option(`${item.icon} ${item.label}`,item.id)));
 function showStatus(message,error=false){status.textContent=message;status.classList.toggle("is-error",error);status.hidden=!message}
 function keyFor(item){return item.id||""}
 function refreshSelection(){const n=placesSelected.size;selectedButton.disabled=!n;selectedButton.textContent=placesSelectedOnly?"Показать все найденные на карте":`Показать выбранные на карте${n?` (${n})`:""}`;updatePlacesMap(placesSelectedOnly)}
 function renderItems(){results.innerHTML=placesResultsPage.map(item=>{const point=item.point&&Number.isFinite(item.point.lat)&&Number.isFinite(item.point.lon)?`${item.point.lon}, ${item.point.lat}`:null;const key=keyFor(item);return `<article class="place-result"><div class="place-result__top"><span class="place-result__source">2GIS</span><label class="place-result__select"><input type="checkbox" data-place-select="${encodeURIComponent(key)}" ${key?"":"disabled"} ${placesSelected.has(key)?"checked":""}><span>Выбрать</span></label></div><h3>${esc(item.name||"Название отсутствует в ответе")}</h3><p class="place-result__address">⌖ ${esc(item.address||"Адрес отсутствует в ответе")}</p><p class="place-result__coords">${point?`Координаты (долгота, широта): ${esc(point)}`:"Координаты отсутствуют в ответе"}</p></article>`}).join("");const total=$("placesResultsCount");if(total)total.textContent=`Получено ${placesResults.length} из ${placesTotal} результатов`;head.hidden=!placesResultsPage.length;pagination.hidden=placesMaxPage<=1;$("placesPageLabel").textContent=`Страница ${placesPage} из ${placesMaxPage}`;$("placesPrev").disabled=placesPage<=1;$("placesNext").disabled=placesPage>=placesMaxPage;$("placesAttribution").hidden=!placesResultsPage.length;refreshSelection()}
 let placesResultsPage=[];let placesTotal=0;
 async function search(page=1){if(placesRequest)return;if(location.protocol==="file:"){showStatus("Для 2GIS API запустите LocalHub через Vercel Dev (npx vercel dev) и откройте выданный localhost URL.",true);return}const cityName=city.value,categoryId=categorySelect.value;if(!cityName||!categoryId){showStatus("Сначала выберите город и категорию.",true);return}placesRequest?.abort();placesRequest=new AbortController();if(page===1){placesResults=[];placesSelected.clear();placesSelectedOnly=false;placesResultsPage=[];placesTotal=0;results.innerHTML="";head.hidden=true;pagination.hidden=true;$("placesAttribution").hidden=true;updatePlacesMap(false)}placesPage=page;button.disabled=true;button.textContent="Ищем…";showStatus("Отправляем запрос к 2GIS через защищённый сервер LocalHub…");try{const query=new URLSearchParams({city:cityName,category:categoryId,page:String(page)});const response=await fetch(`/api/places?${query}`,{signal:placesRequest.signal,headers:{Accept:"application/json"}});const data=await response.json().catch(()=>({}));if(!response.ok){if(data.code==="api_key_missing"&&data.diagnostic){const env=data.diagnostic.deploymentEnvironment||"unknown";throw new Error(`Vercel Function не видит DGIS_API_KEY в окружении ${env}. Проверьте, что переменная добавлена для этого окружения, затем создайте новый deployment.`)}throw new Error(data.error||"Сервер поиска недоступен. На локальном компьютере запустите проект через Vercel Dev.")}placesResultsPage=Array.isArray(data.items)?data.items:[];placesTotal=Number(data.total)||placesResultsPage.length;placesMaxPage=Number(data.maxPage)||0;placesResults.push(...placesResultsPage);showStatus(placesResultsPage.length?"Результаты 2GIS получены. Выберите организации и при необходимости покажите выбранные на карте.":"2GIS не нашёл результатов по выбранным параметрам.");renderItems();updatePlacesMap(false)}catch(error){if(error.name!=="AbortError")showStatus(error.message||"Не удалось выполнить поиск. Попробуйте позже.",true)}finally{placesRequest=null;button.disabled=false;button.innerHTML="Найти организации <span>→</span>"}}
 form.addEventListener("submit",event=>{event.preventDefault();search(1)});$("placesPrev").addEventListener("click",()=>search(Math.max(1,placesPage-1)));$("placesNext").addEventListener("click",()=>search(Math.min(placesMaxPage,placesPage+1)));
 results.addEventListener("change",event=>{const input=event.target.closest("[data-place-select]");if(!input)return;const id=decodeURIComponent(input.dataset.placeSelect);if(!id)return;if(input.checked)placesSelected.add(id);else placesSelected.delete(id);refreshSelection()});
 selectedButton.addEventListener("click",()=>{placesSelectedOnly=!placesSelectedOnly;refreshSelection()});
}
async function syncCloudCatalog(expectedOwner=activeOwner){
 if($("mapCanvas")){refreshLocalMap();return}
 const cloud=window.LocalHubAuth;
 if(!cloud?.ready||expectedOwner!==activeOwner)return;
 const generation=++cloudSyncGeneration;
 const matches=()=>generation===cloudSyncGeneration&&expectedOwner===activeOwner&&(cloud.user?.id||"guest")===expectedOwner;
 try{
  const categoryResult=await cloud.categories();
  if(!matches())return;
  if(!categoryResult.error&&Array.isArray(categoryResult.data)&&categoryResult.data.length){
   CATEGORIES.splice(0,CATEGORIES.length,...categoryResult.data.map(row=>({id:row.id,label:row.name,icon:row.icon||"⌖"})));
   renderChips();renderCategoriesPage();
   for(const id of ["category","mapCategory"]){const select=$(id);if(select)for(const item of CATEGORIES)if(![...select.options].some(option=>option.value===item.id))select.add(new Option(item.label,item.id))}
  }
  const response=await cloud.organizations();
  if(!matches())return;
  if(response.error)cloudNotice("Не удалось загрузить каталог из Supabase.",true);
  else if(Array.isArray(response.data)){
   cloudBusinessIds=new Set(response.data.map(item=>String(item.id)));
   const byId=new Map(businesses.map(item=>[String(item.id),item]));
   for(const item of response.data)byId.set(String(item.id),{...item,id:String(item.id),name:item.name,category:item.category_id,city:item.city,region:item.region,address:item.address,lat:item.lat==null?null:Number(item.lat),lon:item.lon==null?null:Number(item.lon),phone:item.phone,website:item.website,photo:item.photo,hours:item.hours,description:item.description,price_summary:item.price_summary,services:item.services,rating:item.rating==null?null:Number(item.rating),ratingSource:item.rating_source,source:item.source,published_at:item.published_at,updatedAt:item.updated_at,badges:item.badges||[]});
   businesses=[...byId.values()];
   for(const item of response.data)for(const [id,value] of [["cityFilter",item.city],["mapCity",item.city],["regionFilter",item.region]]){const select=$(id);if(value&&select&&![...select.options].some(option=>option.value===value))select.add(new Option(value,value))}
  }
  if(expectedOwner!=="guest"){
   const favoriteResult=await cloud.favoriteIds();
   if(!matches())return;
   if(!favoriteResult.error){favs=new Set(favoriteResult.data||[]);writeScoped(KEY,[...favs],expectedOwner)}
   else cloudNotice("Не удалось загрузить избранное из аккаунта.",true);
  }else favs=new Set(readScoped(KEY,[],expectedOwner));
  if(!matches())return;
  render();detail();refreshLocalMap();await accountPage();
  if(new URLSearchParams(location.search).has("saved")){applySavedSearchFromUrl();render()}
 }catch{if(matches())cloudNotice("Не удалось синхронизировать данные аккаунта.",true)}
}
function handleAuthReady(event){
 const user=event.detail?.user||null;
 const owner=user?.id||"guest";
 const authEvent=event.detail?.event||"";
 const changed=owner!==activeOwner;
 activeOwner=owner;
 if(changed){cloudSyncGeneration++;favs=new Set(readScoped(KEY,[],owner));render();accountPage()}
 if(["INITIAL_SESSION","SIGNED_IN","SIGNED_OUT","CONFIG_MISSING"].includes(authEvent)||changed){
  if(dataLoaded&&window.LocalHubAuth?.ready)syncCloudCatalog(owner);
  else if(dataLoaded)accountPage();
 }
}
document.addEventListener("localhub:language-change",()=>{if(!dataLoaded)return;render();renderCategoriesPage();detail();const select=$("mapCategory"),current=select?.value;if(select){select.replaceChildren(new Option(window.LocalHubI18n?.text("allCategories","Все категории"),"all"));CATEGORIES.forEach(item=>select.add(new Option(`${item.icon} ${category(item.id).label}`,item.id)));select.value=current||"all"}});
initFilters();renderCategoriesPage();loadData().then(()=>{dataLoaded=true;applySavedSearchFromUrl();render();detail();mapPage();addForm();initPlacesSearch();accountPage();if(window.LocalHubAuth?.ready)syncCloudCatalog(activeOwner)});document.addEventListener("localhub:auth-ready",handleAuthReady);




